# Large immutable archives are ignored release assets, deployed to the report's data/ directory.
raw_zip=ASSETS/'raw-debug-1795196244267574.zip'
if not raw_zip.exists():
    inventory=json.loads((DATA/'source-manifest.json').read_text())
    with zipfile.ZipFile(raw_zip,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
        for entry in inventory:
            path=RAW/entry['file'];assert digest(path)==entry['sha256'];z.write(path,'raw-debug-1795196244267574/'+path.name)
    with zipfile.ZipFile(raw_zip) as z:assert z.testzip() is None
analysis_zip=ASSETS/'analysis-full1747.zip'
with zipfile.ZipFile(analysis_zip,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
    for path in sorted(DATA.iterdir()):
        if path.is_file():z.write(path,'computed/'+path.name)
    for name in ['analyze_debug_run.py','review_debug_20261120.py','debug_run_phases.py','METHODS.en.txt','METHODS.cs.txt','provenance.json']:
        z.write(PAGE/'data'/name,name)
checks=[(p.name,digest(p),p.stat().st_size) for p in sorted((PAGE/'data').iterdir()) if p.name not in ('SHA256SUMS','download-sizes.json')]
checks += [(p.name,digest(p),p.stat().st_size) for p in [raw_zip,analysis_zip]]
write(PAGE/'data/SHA256SUMS',''.join(f'{sha}  {name}\n' for name,sha,size in checks))
write(PAGE/'data/download-sizes.json',json.dumps({name:dict(bytes=size,sha256=sha) for name,sha,size in checks},indent=2))
print(json.dumps(dict(page=str(PAGE),raw_zip_bytes=raw_zip.stat().st_size,analysis_zip_bytes=analysis_zip.stat().st_size)))
